def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # A matching diagonal pair defines a line; extend it outward in both
    # directions, stopping at the edge or at another colored cell.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w):
                    continue
                if grid[r2][c2] != color:
                    continue

                for rr, cc, sr, sc in (
                    (r - dr, c - dc, -dr, -dc),
                    (r2 + dr, c2 + dc, dr, dc),
                ):
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != bg:
                            break
                        out[rr][cc] = color
                        rr += sr
                        cc += sc

    return out
